import csv
import io


def parse_csv(raw_csv: str):
    expected_width = 35
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    records = list(csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",",
                              quotechar='"', doublequote=True))

    first_nonempty = None
    first_expected_width = None
    header_index = None

    for index, record in enumerate(records):
        labels = [" ".join(field.split()).casefold() for field in record]
        if not any(labels):
            continue
        if first_nonempty is None:
            first_nonempty = index
        if len(record) != expected_width:
            continue
        if first_expected_width is None:
            first_expected_width = index

        # A wide row of distinct text labels is more likely to be the
        # header than a sparse or numeric preamble record.
        text_labels = {
            label for label in labels
            if label and label[0].isalpha()
        }
        if len(text_labels) >= expected_width * 4 // 5:
            header_index = index
            break

    if header_index is None:
        header_index = first_expected_width
    if header_index is None:
        header_index = first_nonempty
    if header_index is None:
        return {"columns": [], "rows": []}

    columns = records[header_index][:]
    rows = records[header_index + 1:]
    width = max(expected_width, len(columns), max(map(len, rows), default=0))

    # Preserve surplus fields rather than guessing which column they belong to.
    used_names = {name.strip().casefold() for name in columns}
    suffix = 1
    while len(columns) < width:
        name = f"_extra_{suffix}"
        suffix += 1
        if name not in used_names:
            columns.append(name)
            used_names.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
